var _ex = SLP.books.find(function(b){ return b.id === "ex"; });
if (!_ex) throw new Error("data/canon.js must load before ot-03-exodus.js");
(_ex.chapters = _ex.chapters || []).push(
  { n:1, summary:"Israel's family in Egypt grows from seventy souls into a vast multitude that fills the land. After Joseph and all his generation die, a new king rises who knew nothing of Joseph. Fearing that Israel will multiply and side with Egypt's enemies in war, he sets taskmasters over the people to wear them down building the cities Pithom and Raamses — yet the more they are afflicted, the more they multiply. Pharaoh then orders the Hebrew midwives, Shiphrah and Puah, to kill every boy at birth, but they fear God and save the children alive, and God deals well with them and makes them houses. Finally Pharaoh commands all his people to cast every newborn son into the river.",
    context:"The book's opening chapter, traditionally authored by Moses, resumes Genesis generations later as a new Pharaoh enslaves Israel.",
    keyVerses:[
      { ref:"Exodus 1:8", text:"Now there arose up a new king over Egypt, which knew not Joseph." },
      { ref:"Exodus 1:12", text:"But the more they afflicted them, the more they multiplied and grew. And they were grieved because of the children of Israel." },
      { ref:"Exodus 1:17", text:"But the midwives feared God, and did not as the king of Egypt commanded them, but saved the men children alive." }
    ],
    takeaway:"Opposition cannot stop God's covenant people from multiplying; He honors those who fear Him above earthly powers.",
    quiz:[
      { q:"Who were the two Hebrew midwives named in this chapter?", choices:["Shiphrah and Puah","Zipporah and Jochebed","Miriam and Elisheba","Ahisamach and Uri"], a:0, why:"The king of Egypt spake to the Hebrew midwives, Shiphrah and Puah, commanding them to kill the sons and save the daughters alive." },
      { q:"Why did Pharaoh set taskmasters over the children of Israel?", choices:["Because they refused to build his treasure cities","He feared they would multiply and join Egypt's enemies in war","Because they had quarreled with the Egyptians","To prepare them for the journey to Canaan"], a:1, why:"Pharaoh said the people were more and mightier than Egypt, and might join their enemies and fight against them in war." },
      { q:"What principle does the midwives' refusal to obey Pharaoh's order teach?", choices:["Rulers should always be obeyed without question","Clever excuses make disobedience acceptable","When human commands contradict God, fearing God comes first","Courage means telling authorities your true reasons"], a:2, why:"The midwives feared God, did not do as the king commanded, and God dealt well with them and made them houses." }
    ] },
  { n:2, summary:"A Levite woman bears a goodly son and hides him three months; when she can hide him no longer, she lays him in an ark of bulrushes among the flags by the river's brink. Pharaoh's daughter finds the weeping baby, has compassion, and unknowingly hires his own mother to nurse him; she later adopts him and names him Moses, because she drew him out of the water. Grown, Moses kills an Egyptian who was smiting a Hebrew, and when the deed becomes known he flees to Midian. There he helps the seven daughters of the priest of Midian water their flock, marries Zipporah, and names his son Gershom, a stranger in a strange land. As the bondage continues, Israel's cry comes up to God, who hears, remembers His covenant with Abraham, Isaac, and Jacob, and has respect unto them.",
    context:"Moses, born under a death decree, is rescued by Pharaoh's daughter and raised in Egypt's court before fleeing to Midian.",
    keyVerses:[
      { ref:"Exodus 2:24", text:"And God heard their groaning, and God remembered his covenant with Abraham, with Isaac, and with Jacob." },
      { ref:"Exodus 2:10", text:"And the child grew, and she brought him unto Pharaoh's daughter, and he became her son. And she called his name Moses: and she said, Because I drew him out of the water." },
      { ref:"Exodus 2:3", text:"And when she could not longer hide him, she took for him an ark of bulrushes, and daubed it with slime and with pitch, and put the child therein; and she laid it in the flags by the river's brink." }
    ],
    takeaway:"God hears the groaning of the afflicted and works quietly through small rescues toward great deliverance.",
    quiz:[
      { q:"Why did Pharaoh's daughter give the child the name Moses?", choices:["Gershom, because he was a stranger in a strange land","Because he was a goodly child","After the priest of Midian","Because she drew him out of the water"], a:3, why:"She said, Because I drew him out of the water, she called his name Moses." },
      { q:"How did Moses' own mother come to nurse him after the princess found the ark?", choices:["His sister offered to call a Hebrew nurse, who was the child's mother","Pharaoh's daughter knew her at once and hired her","She begged at the palace gate until he was returned","The midwives hid him back in her home"], a:0, why:"His sister asked whether she should call a nurse of the Hebrew women; the maid went and called the child's mother." },
      { q:"What does God's response to Israel's groaning at the chapter's end teach?", choices:["God acts only when His people are strong","God hears the oppressed and remembers His covenant promises","Covenant blessings depend on Israel's devotion in Egypt","Suffering separates God's people from His care"], a:1, why:"God heard their groaning, remembered His covenant with Abraham, Isaac, and Jacob, and looked upon the children of Israel." }
    ] },
  { n:3, summary:"Keeping Jethro's flock at Horeb, the mountain of God, Moses sees a bush that burns but is not consumed, and God calls to him from it: He has surely seen the affliction of His people and is come down to deliver them into a good land flowing with milk and honey. Moses is sent to Pharaoh, yet objects, Who am I? God answers, Certainly I will be with thee, promising a token that Israel will serve God on that mountain. When Moses asks what to say if Israel asks the name of the God of their fathers, the Lord reveals, I AM THAT I AM, His memorial to all generations. God predicts Pharaoh will not let the people go without a mighty hand, and that Israel will leave not empty, spoiling the Egyptians of jewels and raiment.",
    context:"Moses, forty years a shepherd in Midian, is called by God at the burning bush on Horeb, the mountain of God.",
    keyVerses:[
      { ref:"Exodus 3:14", text:"And God said unto Moses, I AM THAT I AM: and he said, Thus shalt thou say unto the children of Israel, I AM hath sent me unto you." },
      { ref:"Exodus 3:2", text:"And the angel of the LORD appeared unto him in a flame of fire out of the midst of a bush: and he looked, and, behold, the bush burned with fire, and the bush was not consumed." },
      { ref:"Exodus 3:12", text:"And he said, Certainly I will be with thee; and this shall be a token unto thee, that I have sent thee: When thou hast brought forth the people out of Egypt, ye shall serve God upon this mountain." }
    ],
    takeaway:"When God sends a hesitant servant, His own presence and name are the true credentials.",
    quiz:[
      { q:"Where was Moses when the bush burned without being consumed?", choices:["On top of mount Sinai","By the river's brink in Egypt","At Horeb, the mountain of God, keeping Jethro's flock","In the wilderness of Sin with the congregation"], a:2, why:"Moses led the flock to the backside of the desert and came to the mountain of God, even to Horeb." },
      { q:"By what name was Moses to tell Israel that God had sent him?", choices:["Jehovah-nissi","God Almighty","The God of the Hebrews","I AM THAT I AM"], a:3, why:"God said, Thus shalt thou say unto the children of Israel, I AM hath sent me unto you." },
      { q:"What does the Lord's promise, 'Certainly I will be with thee,' teach about obedience to a call?", choices:["God's presence is the real answer to feelings of inadequacy","God rarely asks people to do hard things","Signs must come before any obedience is possible","Moses' doubts showed the call was a mistake"], a:0, why:"Moses asked Who am I?, and the Lord's answer was not a list of Moses' strengths but the promise of His own presence." }
    ] },
  { n:4, summary:"Moses fears Israel will not believe him, so the Lord gives three signs: his rod becomes a serpent and then a rod again; his hand turns leprous as snow and is restored; and river water poured on dry land becomes blood. Moses still pleads that he is not eloquent and slow of speech, which kindles the Lord's anger, and Aaron the Levite, who can speak well, is appointed to be his spokesman and mouth while Moses stands to him in God's stead. Moses returns to Egypt with Jethro's blessing, carrying the rod of God. At the inn the Lord meets him and seeks to kill him until Zipporah circumcises their son. Aaron meets him in the mount of God, they gather the elders, Aaron speaks and does the signs, and the people believe, bow their heads, and worship.",
    context:"Moses, still hesitant, is equipped with signs and his brother Aaron as spokesman before returning to Egypt.",
    keyVerses:[
      { ref:"Exodus 4:3", text:"And he said, Cast it on the ground. And he cast it on the ground, and it became a serpent; and Moses fled from before it." },
      { ref:"Exodus 4:11", text:"And the LORD said unto him, Who hath made man's mouth? or who maketh the dumb, or deaf, or the seeing, or the blind? have not I the LORD?" },
      { ref:"Exodus 4:31", text:"And the people believed: and when they heard that the LORD had visited the children of Israel, and that he had looked upon their affliction, then they bowed their heads and worshipped." }
    ],
    takeaway:"God answers weakness with provision — signs for doubters, a mouth for the slow of speech — and still requires obedience.",
    quiz:[
      { q:"What did Moses' rod become when he cast it on the ground?", choices:["A river of blood","A serpent","A staff of brass","A branch of almonds"], a:1, why:"He cast it on the ground, and it became a serpent; Moses fled from before it." },
      { q:"How did the Lord answer Moses' complaint that he was slow of speech?", choices:["Moses was sent home to Midian again","The signs were canceled until Moses improved","Aaron was appointed to speak for him as his mouth","Moses was told to write instead of speak"], a:2, why:"The Lord said Aaron the Levite could speak well and would be Moses' spokesman, to thee instead of a mouth." },
      { q:"What does the Lord's question, 'Who hath made man's mouth?', teach about serving with limitations?", choices:["Limitations disqualify a person from God's work","God only calls those with natural gifts","Weaknesses must be removed before service begins","The Maker of the mouth can equip the mouth He sends"], a:3, why:"The Lord reminded Moses that He who made man's mouth would be with Moses' mouth and teach him what to say." }
    ] },
  { n:5, summary:"Moses and Aaron tell Pharaoh that the LORD God of Israel says, Let my people go, that they may hold a feast unto me in the wilderness. Pharaoh refuses — Who is the LORD? — and the same day strips the brickmakers of their straw, demanding the full tale of bricks while the people glean stubble across Egypt. The Israelite officers are beaten for the missed quota, and their appeal to Pharaoh is answered with the charge, Ye are idle. Coming out from Pharaoh, they confront Moses and Aaron, blaming them for putting a sword in the Egyptians' hand to slay them. Moses turns to the LORD in distress: why hast thou so evil entreated this people? neither hast thou delivered thy people at all.",
    context:"Pharaoh's first encounter with Moses and Aaron ends not in freedom but in heavier burdens for Israel.",
    keyVerses:[
      { ref:"Exodus 5:1", text:"And afterward Moses and Aaron went in, and told Pharaoh, Thus saith the LORD God of Israel, Let my people go, that they may hold a feast unto me in the wilderness." },
      { ref:"Exodus 5:2", text:"And Pharaoh said, Who is the LORD, that I should obey his voice to let Israel go? I know not the LORD, neither will I let Israel go." },
      { ref:"Exodus 5:21", text:"And they said unto them, The LORD look upon you, and judge; because ye have made our savour to be abhorred in the eyes of Pharaoh, and in the eyes of his servants, to put a sword in their hand to slay us." }
    ],
    takeaway:"Faithful obedience may bring sharper trial before deliverance; God invites our honest questions in the meantime.",
    quiz:[
      { q:"What did Pharaoh stop giving the Israelites for making bricks?", choices:["Straw","Water","Clay","Mortar"], a:0, why:"Pharaoh commanded the taskmasters, Ye shall no more give the people straw to make brick; let them gather it themselves." },
      { q:"How did Pharaoh answer the request to let Israel go sacrifice in the wilderness?", choices:["He agreed but required hostages to remain","He said, I know not the LORD, neither will I let Israel go","He delayed the decision seven days","He allowed the elders only to go"], a:1, why:"Pharaoh answered, Who is the LORD, that I should obey his voice? I know not the LORD, neither will I let Israel go." },
      { q:"What does Moses' bold complaint to God at the chapter's end model for believers facing setbacks?", choices:["Discouragement is sin that must be hidden","Complaints should be directed at the people instead","Honest lament can be brought directly to the Lord","Perseverance means never questioning circumstances"], a:2, why:"Moses returned unto the LORD and openly asked why the people had been evil entreated and why deliverance had not come." }
    ] },
  { n:6, summary:"When Moses asks why the people have been so evil entreated, the Lord answers with covenant promises: I will bring you out, rid you of bondage, redeem you with a stretched out arm, take you for a people, and give you the land sworn to Abraham, Isaac, and Jacob. He declares that He appeared to the patriarchs as God Almighty, but by His name JEHOVAH was He not known to them. Moses relays the message, but Israel hearkens not for anguish of spirit and cruel bondage, and Moses protests again that he is of uncircumcised lips. The Lord charges him and Aaron to bring Israel out, and the chapter traces the family heads of Reuben, Simeon, and Levi, showing that Aaron and Moses were sons of Amram and Jochebed, then sends them back to Pharaoh.",
    context:"Discouraged at Egypt's gate, Moses receives renewed covenant promises and his Levite genealogy is traced.",
    keyVerses:[
      { ref:"Exodus 6:3", text:"And I appeared unto Abraham, unto Isaac, and unto Jacob, by the name of God Almighty, but by my name JEHOVAH was I not known to them." },
      { ref:"Exodus 6:6", text:"Wherefore say unto the children of Israel, I am the LORD, and I will bring you out from under the burdens of the Egyptians, and I will rid you out of their bondage, and I will redeem you with a stretched out arm, and with great judgments:" },
      { ref:"Exodus 6:9", text:"And Moses spake so unto the children of Israel: but they hearkened not unto Moses for anguish of spirit, and for cruel bondage." }
    ],
    takeaway:"God's redemption does not depend on our ability to believe it quickly; His word stands firm amid anguish.",
    quiz:[
      { q:"According to the genealogy in this chapter, who were Moses and Aaron's parents?", choices:["Kohath and Elisheba","Izhar and Jochebed","Hur and Miriam","Amram and Jochebed"], a:3, why:"Amram took Jochebed his father's sister to wife, and she bare him Aaron and Moses." },
      { q:"By what name had the Lord appeared to Abraham, Isaac, and Jacob?", choices:["God Almighty","JEHOVAH","I AM THAT I AM","The God of the Hebrews"], a:0, why:"I appeared unto Abraham, unto Isaac, and unto Jacob, by the name of God Almighty, but by my name JEHOVAH was I not known to them." },
      { q:"Why did the children of Israel not hearken to Moses' promise of redemption?", choices:["They preferred to remain in Egypt","Anguish of spirit and cruel bondage left them unable to hear","They doubted that Moses was a Levite","Pharaoh had forbidden them to listen"], a:1, why:"They hearkened not unto Moses for anguish of spirit, and for cruel bondage." }
    ] },
  { n:7, summary:"The Lord makes Moses a god to Pharaoh, with Aaron as his prophet, and announces that He will multiply signs and wonders and harden Pharaoh's heart, so that the Egyptians shall know that He is the LORD. Moses is eighty and Aaron eighty-three when they stand before the king. When Pharaoh demands a miracle, Aaron's rod becomes a serpent; the magicians of Egypt match the sign, but Aaron's rod swallows up their rods, and Pharaoh's heart is hardened. Then the first plague falls: Aaron smites the river, and all the waters of Egypt — streams, rivers, ponds, and pools, even in vessels of wood and stone — turn to blood. The fish die, the river stinks, Egyptians dig along the banks for water, the magicians imitate the sign, and seven days pass while Pharaoh refuses to listen.",
    context:"The contest with Pharaoh opens: the rod becomes a serpent and the Nile is turned to blood, the first plague.",
    keyVerses:[
      { ref:"Exodus 7:5", text:"And the Egyptians shall know that I am the LORD, when I stretch forth mine hand upon Egypt, and bring out the children of Israel from among them." },
      { ref:"Exodus 7:12", text:"For they cast down every man his rod, and they became serpents: but Aaron's rod swallowed up their rods." },
      { ref:"Exodus 7:17", text:"Thus saith the LORD, In this thou shalt know that I am the LORD: behold, I will smite with the rod that is in mine hand upon the waters which are in the river, and they shall be turned to blood." }
    ],
    takeaway:"God's judgments are revelations: every sign on Egypt was meant to make the Egyptians know that He is the LORD.",
    quiz:[
      { q:"How old were Moses and Aaron when they first spoke to Pharaoh?", choices:["Sixty and fifty years old","Ninety and ninety-five years old","Eighty and eighty-three years old","Seventy and seventy-two years old"], a:2, why:"Moses was fourscore years old, and Aaron fourscore and three, when they spake unto Pharaoh." },
      { q:"What happened when Pharaoh's magicians cast down their rods?", choices:["Their rods shattered on the floor","Their rods turned to blood","They could not perform the sign at all","Their rods became serpents, but Aaron's rod swallowed theirs"], a:3, why:"The magicians did likewise, but Aaron's rod swallowed up their rods, yet Pharaoh's heart was hardened." },
      { q:"Why did the Lord send signs and wonders on Egypt?", choices:["That the Egyptians might know that He is the LORD","To make Israel richer than Egypt","Because Moses needed to prove himself to Aaron","To punish the midwives' deception"], a:0, why:"The Lord said the Egyptians shall know that I am the LORD, when I stretch forth mine hand upon Egypt." }
    ] },
  { n:8, summary:"Frogs swarm from the river into houses, bedchambers, ovens, and kneadingtroughs; Pharaoh begs Moses to entreat the Lord and promises to let the people go, but when the frogs die and the land stinks with their heaps, he hardens his heart. Next, Aaron smites the dust and lice cover man and beast; this time the magicians cannot imitate the plague and tell Pharaoh, This is the finger of God — yet he will not hear. Then swarms of flies corrupt Egypt while the land of Goshen, where Israel dwells, is severed and spared. Pharaoh offers to let Israel sacrifice in the land; Moses answers that the sacrifice would be the abomination of the Egyptians, and insists on three days' journey into the wilderness. Pharaoh agrees to let them go, but not far away; the flies depart, and Pharaoh hardens his heart again.",
    context:"Plagues of frogs, lice, and flies press Pharaoh, whose magicians at last confess the finger of God.",
    keyVerses:[
      { ref:"Exodus 8:19", text:"Then the magicians said unto Pharaoh, This is the finger of God: and Pharaoh's heart was hardened, and he hearkened not unto them; as the LORD had said." },
      { ref:"Exodus 8:22", text:"And I will sever in that day the land of Goshen, in which my people dwell, that no swarms of flies shall be there; to the end thou mayest know that I am the LORD in the midst of the earth." },
      { ref:"Exodus 8:15", text:"But when Pharaoh saw that there was respite, he hardened his heart, and hearkened not unto them; as the LORD had said." }
    ],
    takeaway:"Glimpses of relief test the heart: those who forget God when the pressure lifts will harden again.",
    quiz:[
      { q:"What did the magicians confess after failing to bring forth lice?", choices:["Moses is greater than Pharaoh","This is the finger of God","Israel's God will destroy Egypt","Let the people go at once"], a:1, why:"They could not bring forth lice, so they said unto Pharaoh, This is the finger of God." },
      { q:"Why did Moses refuse Pharaoh's compromise of sacrificing within Egypt?", choices:["The journey was too short to matter","Israel feared the wilderness journey","Sacrificing the abomination of the Egyptians before their eyes would provoke stoning","God had not yet chosen a place of sacrifice"], a:2, why:"Moses said it was not meet so to do, for the sacrifice would be the abomination of the Egyptians, and they would stone them." },
      { q:"What does Pharaoh's cycle of promising and hardening after relief warn against?", choices:["Making requests to God during crisis","Seeking help from righteous intercessors","Taking vows in times of trouble","Forgetting commitments the moment relief comes"], a:3, why:"When Pharaoh saw there was respite, he hardened his heart and hearkened not, and the pattern repeated with the frogs and the flies." }
    ] },
  { n:9, summary:"A grievous murrain falls on Egypt's cattle — horses, asses, camels, oxen, and sheep — while not one of Israel's cattle dies; Pharaoh sends and verifies it, yet will not let the people go. Moses sprinkles ashes of the furnace toward heaven, and boils break forth with blains on man and beast, so the magicians cannot even stand before Moses. The Lord declares He could have cut Pharaoh off, but has raised him up to show His power and make His name declared throughout all the earth. Hail such as Egypt has never seen falls with fire mingled, smashing every herb and tree — except in Goshen — after warning that whoever fears the word of the LORD brings servants and cattle home. Pharaoh confesses, I have sinned this time: the LORD is righteous, but when the thunder and hail cease, he sins yet more and hardens his heart.",
    context:"Murrain, boils, and hail strike Egypt while the land of Goshen, where Israel dwells, is spared.",
    keyVerses:[
      { ref:"Exodus 9:6", text:"And the LORD did that thing on the morrow, and all the cattle of Egypt died: but of the cattle of the children of Israel died not one." },
      { ref:"Exodus 9:16", text:"And in very deed for this cause have I raised thee up, for to shew in thee my power; and that my name may be declared throughout all the earth." },
      { ref:"Exodus 9:27", text:"And Pharaoh sent, and called for Moses and Aaron, and said unto them, I have sinned this time: the LORD is righteous, and I and my people are wicked." }
    ],
    takeaway:"Warnings obeyed bring protection; the fear of the word of the LORD is the beginning of deliverance from judgment.",
    quiz:[
      { q:"How many of the cattle of the children of Israel died in the murrain?", choices:["Not one","One in ten","All the firstborn","Half the herds"], a:0, why:"All the cattle of Egypt died, but of the cattle of the children of Israel died not one." },
      { q:"Why, according to the Lord, had Pharaoh been raised up?", choices:["Because Egypt needed a wise ruler","To show God's power, that His name might be declared throughout all the earth","Because Israel's faith needed testing","So the hail would have a witness in court"], a:1, why:"For this cause have I raised thee up, for to shew in thee my power, and that my name may be declared throughout all the earth." },
      { q:"What did those who feared the word of the LORD do before the hail came?", choices:["Fled to Goshen and joined Israel","Prayed that the hail would miss their fields","Brought their servants and cattle into the houses","Buried their idols under the threshing floors"], a:2, why:"He that feared the word of the LORD among the servants of Pharaoh made his servants and his cattle flee into the houses." }
    ] },
  { n:10, summary:"The Lord explains that Pharaoh's hardened heart serves a purpose: these signs are to be told in the ears of sons and sons' sons, that Israel may know that He is the LORD. Warned of locusts, Pharaoh's servants beg him to let the men go, for Egypt is destroyed. Pharaoh offers to release only the men; Moses answers that young and old, sons and daughters, flocks and herds must go to hold a feast unto the LORD. The east wind brings locusts that darken the land and devour everything the hail left; Pharaoh confesses sin, and a mighty west wind casts the locusts into the Red sea. Then a darkness that may be felt covers Egypt three days, while all Israel has light in their dwellings. Pharaoh's last offer lets the people go without their cattle; Moses refuses, and Pharaoh commands him to see his face no more.",
    context:"Locusts and a three-day darkness bring Egypt to the brink as Pharaoh refuses every compromise.",
    keyVerses:[
      { ref:"Exodus 10:2", text:"And that thou mayest tell in the ears of thy son, and of thy son's son, what things I have wrought in Egypt, and my signs which I have done among them; that ye may know how that I am the LORD." },
      { ref:"Exodus 10:23", text:"They saw not one another, neither rose any from his place for three days: but all the children of Israel had light in their dwellings." },
      { ref:"Exodus 10:28", text:"And Pharaoh said unto him, Get thee from me, take heed to thyself, see my face no more; for in that day thou seest my face thou shalt die." }
    ],
    takeaway:"God asks for whole devotion — not just the men, but sons and daughters, flocks and herds, nothing held back.",
    quiz:[
      { q:"What removed the locusts from Egypt, and where did they go?", choices:["Rain washed them into the Nile","The east wind drove them to the wilderness","They died and were gathered on heaps","A mighty strong west wind cast them into the Red sea"], a:3, why:"The LORD turned a mighty strong west wind, which took away the locusts and cast them into the Red sea; there remained not one." },
      { q:"How did Pharaoh's offer after the darkness still fall short of the Lord's demand?", choices:["The people could go, but their flocks and herds had to stay","Only the elders could travel to sacrifice","The people could go, but Moses had to remain","Three days were granted instead of a full journey"], a:0, why:"Pharaoh said, Go ye, serve the LORD; only let your flocks and your herds be stayed — and Moses answered there shall not an hoof be left behind." },
      { q:"Why does the Lord want these signs told to sons and grandsons?", choices:["To shame the memory of Pharaoh forever","So later generations may know that He is the LORD","Because Israel kept records of every plague","To warn children against visiting Egypt"], a:1, why:"The signs were wrought that thou mayest tell in the ears of thy son, and of thy son's son... that ye may know how that I am the LORD." }
    ] },
  { n:11, summary:"One plague more is announced: afterwards Pharaoh will surely thrust Israel out altogether. Israel is told to borrow of their neighbours jewels of silver and gold, and the Lord gives the people favour in Egyptian eyes, while Moses grows very great in the land. About midnight the LORD will go out into the midst of Egypt, and all the firstborn shall die, from the firstborn of Pharaoh on his throne to the firstborn of the maidservant behind the mill, and all the firstborn of beasts. A great cry will fill the land, such as never was and never shall be again — but against any of the children of Israel shall not a dog move his tongue, that all may know the LORD puts a difference between the Egyptians and Israel. After foretelling that Pharaoh's servants will bow to him and beg the people to go, Moses leaves Pharaoh's presence in great anger.",
    context:"The tenth and final plague is announced before Pharaoh after Israel is told to ask for jewels of silver and gold.",
    keyVerses:[
      { ref:"Exodus 11:5", text:"And all the firstborn in the land of Egypt shall die, from the firstborn of Pharaoh that sitteth upon his throne, even unto the firstborn of the maidservant that is behind the mill; and all the firstborn of beasts." },
      { ref:"Exodus 11:7", text:"But against any of the children of Israel shall not a dog move his tongue, against man or beast: that ye may know how that the LORD doth put a difference between the Egyptians and Israel." },
      { ref:"Exodus 11:3", text:"And the LORD gave the people favour in the sight of the Egyptians. Moreover the man Moses was very great in the land of Egypt, in the sight of Pharaoh's servants, and in the sight of the people." }
    ],
    takeaway:"God's final judgments make an eternal difference visible between those who hear Him and those who refuse.",
    quiz:[
      { q:"Who in Egypt were to die in the plague announced in this chapter?", choices:["Only the sons of Pharaoh","Every Egyptian soldier in the army","All the firstborn in the land, of man and beast","The magicians and the priests alone"], a:2, why:"All the firstborn in the land of Egypt shall die, from the firstborn of Pharaoh even unto the firstborn of the maidservant, and all the firstborn of beasts." },
      { q:"What were the Israelites told to ask of their Egyptian neighbours?", choices:["Bread and water for the journey","Chariots for the old and the young","Written letters of release","Jewels of silver and jewels of gold"], a:3, why:"Speak now in the ears of the people... let every man borrow of his neighbour... jewels of silver, and jewels of gold." },
      { q:"What does the promise that not a dog would move his tongue against Israel reveal about God's judgments?", choices:["He makes a real distinction between His people and those who defy Him","He protects Israel because of their military strength","He spares the innocent automatically in every nation","His judgments fall randomly on all alike"], a:0, why:"That ye may know how that the LORD doth put a difference between the Egyptians and Israel." }
    ] },
  { n:12, summary:"The Passover is instituted in the first month of Israel's calendar. Each house takes a lamb without blemish on the tenth day and kills it on the fourteenth, strikes its blood on the side posts and upper door post, and eats it roasted with fire, with unleavened bread and bitter herbs, dressed for travel and eating in haste: it is the LORD's passover. That night the Lord smites all the firstborn of Egypt and judges her gods, but the blood is the token by which He passes over Israel's houses. The feast of unleavened bread is kept seven days as a perpetual ordinance, children included in its meaning. At midnight a great cry rises, and Pharaoh commands Israel to rise and go. The people spoil the Egyptians and journey from Rameses to Succoth, about six hundred thousand men on foot, after four hundred and thirty years.",
    context:"The Passover is instituted and kept on the night Israel is thrust out of Egypt after four hundred and thirty years.",
    keyVerses:[
      { ref:"Exodus 12:13", text:"And the blood shall be to you for a token upon the houses where ye are: and when I see the blood, I will pass over you, and the plague shall not be upon you to destroy you, when I smite the land of Egypt." },
      { ref:"Exodus 12:11", text:"And thus shall ye eat it; with your loins girded, your shoes on your feet, and your staff in your hand; and ye shall eat it in haste: it is the LORD's passover." },
      { ref:"Exodus 12:37", text:"And the children of Israel journeyed from Rameses to Succoth, about six hundred thousand on foot that were men, beside children." }
    ],
    takeaway:"Deliverance is by the blood of the lamb applied in obedient faith; judgment passes over the sheltered house.",
    quiz:[
      { q:"On which day of the month was the passover lamb to be killed?", choices:["The tenth","The fourteenth","The seventh","The twenty-first"], a:1, why:"Ye shall keep it up until the fourteenth day of the same month: and the whole assembly of the congregation of Israel shall kill it in the evening." },
      { q:"What marked an Israelite house so the destroyer would not enter?", choices:["A lamp burning all night in the window","The family kneeling at the threshold","The blood of the lamb on the lintel and two side posts","Hyssop hung above every doorway"], a:2, why:"When he seeth the blood upon the lintel, and on the two side posts, the LORD will pass over the door." },
      { q:"What does eating the passover with loins girded, shoes on feet, staff in hand teach about faith?", choices:["Israel loved the customs of Egypt","Faith prepares to act on God's deliverance the moment it comes","Meals were eaten standing in all cultures","The lamb's meat had to be eaten quickly to stay fresh"], a:3, why:"They were to eat it in haste, for that night the Lord would bring them out — it is the LORD's passover." }
    ] },
  { n:13, summary:"The Lord claims all the firstborn of man and beast for Himself, and Moses tells the people to remember the day they came out of Egypt, the house of bondage: no leavened bread is eaten, the feast is kept in the month Abib, and fathers explain to their sons that the ordinance recalls the Lord's strong hand. Every firstling is set apart — firstling asses redeemed with a lamb, and all the firstborn of Israel's children redeemed — so that the token on the hand and frontlets between the eyes testify that the LORD brought Israel out by strength of hand. God leads them not by the way of the Philistines, lest the people repent at the sight of war, but toward the wilderness of the Red sea; Moses carries the bones of Joseph, sworn by Joseph long before. Israel encamps in Etham, and the LORD goes before them by day in a pillar of cloud and by night in a pillar of fire, never taken away.",
    context:"Israel marches out, consecrating the firstborn, carrying Joseph's bones, and following the pillar of cloud and fire.",
    keyVerses:[
      { ref:"Exodus 13:21", text:"And the LORD went before them by day in a pillar of a cloud, to lead them the way; and by night in a pillar of fire, to give them light; to go by day and night:" },
      { ref:"Exodus 13:2", text:"Sanctify unto me all the firstborn, whatsoever openeth the womb among the children of Israel, both of man and of beast: it is mine." },
      { ref:"Exodus 13:3", text:"And Moses said unto the people, Remember this day, in which ye came out from Egypt, out of the house of bondage; for by strength of hand the LORD brought you out from this place: there shall no leavened bread be eaten." }
    ],
    takeaway:"Memorials of deliverance keep faith alive; God leads by the longer road when the short one would undo us.",
    quiz:[
      { q:"In what month did Israel come out of Egypt, according to this chapter?", choices:["Abib","Tammuz","Ethanim","Zif"], a:0, why:"This day came ye out in the month Abib." },
      { q:"Why did God not lead Israel through the way of the land of the Philistines?", choices:["The Philistines refused them passage","Lest the people see war and return to Egypt","The road was blocked by Egyptian garrisons","The pillar of cloud could not travel that way"], a:1, why:"God said, Lest peradventure the people repent when they see war, and they return to Egypt." },
      { q:"What does Moses carrying Joseph's bones demonstrate about faith across generations?", choices:["Egyptian customs had to be respected for the dead","Relics guaranteed victory in battle","Faith acts on promises made long before their fulfillment","The dead could not rest until they left Egypt"], a:2, why:"Joseph had straitly sworn the children of Israel, saying, God will surely visit you; and ye shall carry up my bones away hence with you." }
    ] },
  { n:14, summary:"Israel encamps by the sea before Pi-hahiroth, and the Lord hardens Pharaoh's heart: the king pursues with six hundred chosen chariots and all the chariots of Egypt, overtaking Israel by the water. Terrified, the people cry that it would have been better to serve the Egyptians than die in the wilderness. Moses answers, Fear ye not, stand still, and see the salvation of the LORD; the Egyptians they see today they will see no more, for the LORD shall fight for them. Told to go forward, Moses stretches his hand over the sea; a strong east wind divides it, Israel crosses on dry ground between walls of water, and the pillar of cloud stands between them and the Egyptian army, light by night for Israel and darkness for Egypt. The Lord troubles the host, takes off their chariot wheels, and at Moses' word the waters return and cover the whole army — not one remains. Israel sees the great work, fears the LORD, and believes the LORD and his servant Moses.",
    context:"Hemmed in at the sea with Pharaoh's chariots behind, Israel crosses on dry ground as the army is drowned.",
    keyVerses:[
      { ref:"Exodus 14:14", text:"The LORD shall fight for you, and ye shall hold your peace." },
      { ref:"Exodus 14:21", text:"And Moses stretched out his hand over the sea; and the LORD caused the sea to go back by a strong east wind all that night, and made the sea dry land, and the waters were divided." },
      { ref:"Exodus 14:31", text:"And Israel saw that great work which the LORD did upon the Egyptians: and the people feared the LORD, and believed the LORD, and his servant Moses." }
    ],
    takeaway:"Between army and sea, faith stands still before God's salvation and then goes forward at His word.",
    quiz:[
      { q:"How many chosen chariots did Pharaoh take in pursuit of Israel?", choices:["Fifty","Three hundred","One thousand","Six hundred"], a:3, why:"He took six hundred chosen chariots, and all the chariots of Egypt, and captains over every one of them." },
      { q:"What did the pillar of cloud do between the two camps that night?", choices:["Stood between them, darkness to the Egyptians and light to Israel","Poured rain on the Egyptian chariots","Lifted and led Israel back toward Egypt","Became a wall of brass around the camp"], a:0, why:"It came between the camp of the Egyptians and the camp of Israel; it was a cloud and darkness to them, but it gave light by night to these." },
      { q:"What does Moses' command, 'stand still, and see the salvation of the LORD,' teach about faith in impossible situations?", choices:["Waiting always replaces action for believers","Faith faces threat with trust in what only God can do","Courage comes from counting your own numbers","Retreat is wiser than standing before overwhelming odds"], a:1, why:"With the sea before them and chariots behind, the people were told to fear not, for the LORD would fight for them while they held their peace." }
    ] },
  { n:15, summary:"Moses and the children of Israel sing to the LORD: He has triumphed gloriously, the horse and his rider thrown into the sea. The song names Him strength, song, salvation, and a man of war, recalls Pharaoh's chosen captains sinking as a stone, asks who is like the LORD among the gods, and looks ahead to His leading the redeemed to His holy habitation, while Edom, Moab, and Canaan tremble. Miriam the prophetess takes a timbrel, and the women go out after her with dances. Three days into the wilderness of Shur they find no water; at Marah the waters are bitter, the people murmur, and the LORD shows Moses a tree which, cast into the waters, makes them sweet. There the Lord proves them and promises health, saying, I am the LORD that healeth thee. They come to Elim with twelve wells of water and threescore and ten palm trees.",
    context:"After the sea victory Moses and Israel sing to the Lord, then taste bitterness and healing at Marah.",
    keyVerses:[
      { ref:"Exodus 15:2", text:"The LORD is my strength and song, and he is become my salvation: he is my God, and I will prepare him an habitation; my father's God, and I will exalt him." },
      { ref:"Exodus 15:11", text:"Who is like unto thee, O LORD, among the gods? who is like thee, glorious in holiness, fearful in praises, doing wonders?" },
      { ref:"Exodus 15:26", text:"And said, If thou wilt diligently hearken to the voice of the LORD thy God, and wilt do that which is right in his sight, and wilt give ear to his commandments, and keep all his statutes, I will put none of these diseases upon thee, which I have brought upon the Egyptians: for I am the LORD that healeth thee." }
    ],
    takeaway:"Redemption is answered with song; the God who delivers also heals, testing and teaching His people on the road.",
    quiz:[
      { q:"What marked Israel's next encampment after Marah, at Elim?", choices:["Seven wells and thirty palm trees","A spring flowing from a rock","Twelve wells of water and seventy palm trees","An oasis of fig and pomegranate trees"], a:2, why:"They came to Elim, where were twelve wells of water, and threescore and ten palm trees: and they encamped there by the waters." },
      { q:"How were the bitter waters of Marah made sweet?", choices:["Aaron threw salt into the pool","Moses struck the water with his rod","The people dug new wells beside it","The LORD showed Moses a tree, which he cast into the waters"], a:3, why:"The LORD shewed him a tree, which when he had cast into the waters, the waters were made sweet." },
      { q:"What does the song after the sea crossing teach about responding to God's victories?", choices:["Deliverance should be celebrated and remembered in praise to God","Victory songs were reserved for special feasts only","Praise belongs to the human leader who acted boldly","Music distracts from the seriousness of judgment"], a:0, why:"Moses and Israel sang unto the LORD, recounting His triumph; Miriam answered with timbrels and dances." }
    ] },
  { n:16, summary:"In the wilderness of Sin, the whole congregation murmurs against Moses and Aaron, wishing they had died in Egypt by the flesh pots and full bread. The Lord promises to rain bread from heaven, testing whether the people will walk in His law; quails cover the camp that evening, and in the morning a small round thing lies with the dew, which Israel calls manna because they know not what it is. Each gathers an omer according to his eating; leftovers kept till morning breed worms and stink, but on the sixth day a double portion is gathered and keeps, for tomorrow is the rest of the holy sabbath. Some go out on the seventh day and find none, and the Lord asks how long they will refuse to keep His commandments. The manna is like coriander seed, white, tasting of wafers made with honey; an omer of it is laid up before the Testimony, and Israel eats manna forty years until they reach Canaan's borders.",
    context:"In the wilderness of Sin between Elim and Sinai, murmuring Israel receives quails at even and bread from heaven each morning.",
    keyVerses:[
      { ref:"Exodus 16:4", text:"Then said the LORD unto Moses, Behold, I will rain bread from heaven for you; and the people shall go out and gather a certain rate every day, that I may prove them, whether they will walk in my law, or no." },
      { ref:"Exodus 16:15", text:"And when the children of Israel saw it, they said one to another, It is manna: for they wist not what it was. And Moses said unto them, This is the bread which the LORD hath given you to eat." },
      { ref:"Exodus 16:29", text:"See, for that the LORD hath given you the sabbath, therefore he giveth you on the sixth day the bread of two days; abide ye every man in his place, let no man go out of his place on the seventh day." }
    ],
    takeaway:"God gives daily bread to teach daily trust, and sets His sabbath as a rhythm of rest within His provision.",
    quiz:[
      { q:"What covered the camp in the evening as the Lord promised flesh to eat?", choices:["Doves","Quails","Locusts","Dew"], a:1, why:"At even the quails came up, and covered the camp." },
      { q:"What happened to manna that was left until morning, except on the sixth day?", choices:["It turned bitter like Marah's water","It doubled in amount","It bred worms and stank","It melted with the sun"], a:2, why:"Some left of it until the morning, and it bred worms, and stank: and Moses was wroth with them." },
      { q:"Why did the Lord double the manna on the sixth day?", choices:["To reward those who gathered fastest","Because the seventh day was needed for travel","So the rulers could store extra for the camp","Because the seventh day was the sabbath of rest unto the LORD"], a:3, why:"Tomorrow is the rest of the holy sabbath unto the LORD; the sixth day's bread of two days kept without spoiling." }
    ] },
  { n:17, summary:"At Rephidim there is no water, and the people chide with Moses and tempt the LORD, asking, Is the LORD among us, or not? The Lord tells Moses to take the elders and the rod with which he smote the river, and to smite the rock in Horeb; water comes out for the people, and the place is named Massah and Meribah. Then Amalek fights with Israel, and Moses tells Joshua to choose men for battle while he stands on the hill with the rod of God. When Moses' hands are held up Israel prevails; when they drop, Amalek prevails — so Aaron and Hur seat him on a stone and steady his hands until the going down of the sun, and Joshua discomfits Amalek with the edge of the sword. The victory is written for a memorial, and Moses builds an altar called Jehovah-nissi, for the LORD will have war with Amalek from generation to generation.",
    context:"At Rephidim water comes from the rock, and Joshua defeats Amalek while Moses' hands are held steady.",
    keyVerses:[
      { ref:"Exodus 17:6", text:"Behold, I will stand before thee there upon the rock in Horeb; and thou shalt smite the rock, and there shall come water out of it, that the people may drink. And Moses did so in the sight of the elders of Israel." },
      { ref:"Exodus 17:12", text:"But Moses' hands were heavy; and they took a stone, and put it under him, and he sat thereon; and Aaron and Hur stayed up his hands, the one on the one side, and the other on the other side; and his hands were steady until the going down of the sun." },
      { ref:"Exodus 17:15", text:"And Moses built an altar, and called the name of it Jehovah-nissi:" }
    ],
    takeaway:"The Lord supplies water from the rock and victory from heaven; His battles are won with uplifted, sustained hands.",
    quiz:[
      { q:"Whom did Moses choose to lead the fight against Amalek?", choices:["Joshua","Aaron","Hur","Caleb"], a:0, why:"Moses said unto Joshua, Choose us out men, and go out, fight with Amalek." },
      { q:"Why was the place of the water from the rock named Massah and Meribah?", choices:["For the sweetness of the waters","Because Israel chided with Moses and tempted the LORD there","For the altar built beside the rock","Because the rock was split in two"], a:1, why:"He called the name of the place Massah, and Meribah, because of the chiding of the children of Israel, and because they tempted the LORD." },
      { q:"What does Aaron and Hur holding up Moses' hands teach about the work of the Lord?", choices:["Leaders must never show weakness publicly","Battle outcomes depend on physical stamina","Prayer is effective only on mountaintops","God's work is sustained when others share and support the burden"], a:2, why:"When Moses' hands were heavy, Aaron and Hur stayed them up, one on one side and one on the other, until the going down of the sun." }
    ] },
  { n:18, summary:"Jethro, priest of Midian and Moses' father in law, brings Zipporah and her two sons, Gershom and Eliezer, to Moses at the mount of God. Moses recounts all the LORD did to Pharaoh and Egypt, and Jethro rejoices, blesses the LORD, and confesses that the LORD is greater than all gods, offering burnt offerings while Aaron and the elders eat bread with him. The next day Moses sits alone to judge the people from morning to evening. Jethro warns that the burden is too heavy and will wear away both Moses and the people, and counsels him to stand before God for the people, teach them ordinances and laws, and choose able men who fear God, men of truth, hating covetousness, as rulers of thousands, hundreds, fifties, and tens to judge small matters, with hard causes brought to Moses. Moses hearkens and does all that Jethro had said, then sends him to his own land.",
    context:"Jethro reunites Moses with his family at the mount of God and counsels him to share the judging burden.",
    keyVerses:[
      { ref:"Exodus 18:11", text:"Now I know that the LORD is greater than all gods: for in the thing wherein they dealt proudly he was above them." },
      { ref:"Exodus 18:21", text:"Moreover thou shalt provide out of all the people able men, such as fear God, men of truth, hating covetousness; and place such over them, to be rulers of thousands, and rulers of hundreds, rulers of fifties, and rulers of tens:" },
      { ref:"Exodus 18:22", text:"And let them judge the people at all seasons: and it shall be, that every great matter they shall bring unto thee, but every small matter they shall judge: so shall it be easier for thyself, and they shall bear the burden with thee." }
    ],
    takeaway:"Shared, righteous judgment preserves both the leader and the people; humility listens to wise counsel.",
    quiz:[
      { q:"Which of Moses' sons are named as returning with Jethro and Zipporah?", choices:["Nadab and Abihu","Massah and Meribah","Phinehas and Eleazar","Gershom and Eliezer"], a:3, why:"Her two sons were Gershom, for Moses said I have been an alien in a strange land, and Eliezer, for the God of my father was mine help." },
      { q:"What kind of men did Jethro tell Moses to appoint as rulers over the people?", choices:["Able men who fear God, men of truth, hating covetousness","Strong warriors from every tribe","The oldest men in each family","Scribes trained in Egyptian courts"], a:0, why:"Thou shalt provide out of all the people able men, such as fear God, men of truth, hating covetousness." },
      { q:"What does Jethro's counsel reveal about how heavy responsibilities should be carried?", choices:["A true leader judges every matter personally","Delegating to righteous, capable people sustains both leader and people","Matters of judgment should be decided by the crowd","Counsel from family should be politely declined"], a:1, why:"If thou shalt do this thing, and God command thee so, then thou shalt be able to endure, and all this people shall also go to their place in peace." }
    ] },
  { n:19, summary:"In the third month Israel comes to the wilderness of Sinai and camps before the mount. Moses goes up to God, who offers a covenant: if Israel obeys His voice and keeps His covenant, they shall be a peculiar treasure above all people, a kingdom of priests, and an holy nation. All the people answer together, All that the LORD hath spoken we will do. The Lord will come down in the sight of all the people upon mount Sinai on the third day; Moses sanctifies the people, they wash their clothes, and strict bounds are set — whosoever touches the mount shall surely be put to death. On the third day come thunders and lightnings, a thick cloud, and an exceeding loud trumpet; Sinai smokes because the LORD descends upon it in fire, and the whole mount quakes greatly. The Lord calls Moses to the top, then sends him down to charge the people and the priests not to break through, Moses and Aaron alone to come up.",
    context:"Israel camps before mount Sinai and is sanctified for the third day, when the Lord descends in fire.",
    keyVerses:[
      { ref:"Exodus 19:5", text:"Now therefore, if ye will obey my voice indeed, and keep my covenant, then ye shall be a peculiar treasure unto me above all people: for all the earth is mine:" },
      { ref:"Exodus 19:6", text:"And ye shall be unto me a kingdom of priests, and an holy nation. These are the words which thou shalt speak unto the children of Israel." },
      { ref:"Exodus 19:18", text:"And mount Sinai was altogether on a smoke, because the LORD descended upon it in fire: and the smoke thereof ascended as the smoke of a furnace, and the whole mount quaked greatly." }
    ],
    takeaway:"Covenant identity — God's treasured people — is entered through obedience and prepared for with reverence.",
    quiz:[
      { q:"What was the penalty for any person or beast that touched the border of the mount?", choices:["Being cast out of the camp","A ransom of half a shekel","Surely being put to death","Seven days of separation"], a:2, why:"Whosoever toucheth the mount shall be surely put to death: there shall not an hand touch it, but he shall surely be stoned, or shot through." },
      { q:"What three things did the Lord promise Israel would be if they obeyed His covenant?", choices:["A mighty army, a wise court, and builders of His house","Prophets, priests, and kings","Sowers, reapers, and keepers of the vineyard","A peculiar treasure, a kingdom of priests, and an holy nation"], a:3, why:"Then ye shall be a peculiar treasure unto me above all people... a kingdom of priests, and an holy nation." },
      { q:"What does the sanctifying, washing, and setting of bounds before the Lord's descent teach about meeting God?", choices:["Reverent preparation honors God's holiness","Fear was needed because Moses' words were unclear","Cleanliness rules were borrowed from Egyptian temples","The mountain was dangerous because of its height"], a:0, why:"The people were sanctified and their clothes washed, with bounds round the mount, for the third day the LORD would come down in the sight of all the people." }
    ] },
  { n:20, summary:"God speaks the words of the covenant from Sinai, beginning with who He is: the LORD thy God, which brought thee out of the land of Egypt, out of the house of bondage. Then follow the Ten Commandments — no other gods before Him; no graven image, nor bowing down to them; not taking His name in vain; remembering the sabbath day to keep it holy, resting the seventh day as the Lord rested after six days of creation; honouring father and mother so that days may be long in the land; and thou shalt not kill, commit adultery, steal, bear false witness, or covet a neighbour's house, wife, servants, ox, ass, or any thing that is his. The people, seeing the thunderings, lightnings, trumpet noise, and smoking mountain, stand afar off and beg Moses to speak to them, not God, lest they die; Moses says God is come to prove them, that His fear may keep them from sin. Altars are to be of earth or unhewn stone, without steps.",
    context:"From the smoking mount, the Lord speaks the Ten Commandments directly to the assembled, trembling congregation.",
    keyVerses:[
      { ref:"Exodus 20:2", text:"I am the LORD thy God, which have brought thee out of the land of Egypt, out of the house of bondage." },
      { ref:"Exodus 20:8", text:"Remember the sabbath day, to keep it holy." },
      { ref:"Exodus 20:12", text:"Honour thy father and thy mother: that thy days may be long upon the land which the LORD thy God giveth thee." }
    ],
    takeaway:"The law begins with the Redeemer's identity: right worship of God orders every duty to neighbor and self.",
    quiz:[
      { q:"Which commandment is introduced with the word 'Remember'?", choices:["The third, on the Lord's name","The fourth, the sabbath day","The fifth, honouring parents","The tenth, against coveting"], a:1, why:"Remember the sabbath day, to keep it holy." },
      { q:"How did the people respond when they saw the thunderings, lightnings, and the mountain smoking?", choices:["They drew near the mount to gaze","They offered sacrifices at once","They removed and stood afar off, asking Moses to speak with them instead of God","They asked for a covenant signed in blood"], a:2, why:"When the people saw it, they removed, and stood afar off, and said, Speak thou with us, and we will hear: but let not God speak with us, lest we die." },
      { q:"What does the commandment against coveting reveal about what God examines?", choices:["Only actions that harm another person","Public conduct in the congregation","Words spoken against a neighbor","The desires of the heart, not merely outward deeds"], a:3, why:"Thou shalt not covet thy neighbour's house... nor any thing that is thy neighbour's — a command aimed at desire itself." }
    ] },
  { n:21, summary:"The judgments set before Israel begin with the Hebrew servant: he serves six years and goes out free in the seventh, unless he loves his master and will not go out, in which case his ear is bored with an awl at the door post for ever. Maidservants are protected from neglect. Death is appointed for murder, for smiting or cursing father or mother, and for stealing a man; the unplanned slayer may flee to a place the Lord appoints, and quarrels that maim but do not kill require payment for lost time and thorough healing. Personal injury answers with the famous rule of like for like — life for life, eye for eye, tooth for tooth — while a servant freed for a destroyed eye or tooth shows the law's care for the vulnerable. A goring ox is stoned; a warned owner who lets a known gorer loose may pay with his life, and pits and damaged cattle require honest restitution between neighbors.",
    context:"The judgments given at Sinai begin, covering Hebrew servants, violence, and injuries between neighbors.",
    keyVerses:[
      { ref:"Exodus 21:2", text:"If thou buy an Hebrew servant, six years he shall serve: and in the seventh he shall go out free for nothing." },
      { ref:"Exodus 21:12", text:"He that smiteth a man, so that he die, shall be surely put to death." },
      { ref:"Exodus 21:24", text:"Eye for eye, tooth for tooth, hand for hand, foot for foot," }
    ],
    takeaway:"God's law holds life sacred and equal, restrains revenge, and defends the powerless with real protections.",
    quiz:[
      { q:"How long did a Hebrew servant serve before going out free?", choices:["Six years","Three years","Ten years","Seven years"], a:0, why:"If thou buy an Hebrew servant, six years he shall serve: and in the seventh he shall go out free for nothing." },
      { q:"What marked the servant who chose to stay with his master because he loved him?", choices:["A ring on his right hand","His ear bored through with an awl at the door post","A scarlet cord on his wrist","His name written in the book of the covenant"], a:1, why:"His master shall bring him unto the judges, and to the door, or unto the door post; and his master shall bore his ear through with an awl." },
      { q:"What principle does 'eye for eye, tooth for tooth' establish about justice?", choices:["Victims may exact personal revenge","All injuries are equal and deserve the same fine","Punishment must be proportionate to the wrong done, not excessive","Property losses outweigh injuries to persons"], a:2, why:"The judgment gave life for life, eye for eye, tooth for tooth — a measured, judicial penalty rather than endless retaliation." }
    ] },
  { n:22, summary:"Restitution anchors the next judgments: a stolen ox killed or sold is repaid fivefold, a sheep fourfold; a thief breaking in at night may be smitten without bloodguilt, but by daylight he must make full restitution, selling himself if he has nothing. Goods found alive in a thief's hand are restored double; burnt fields, entrusted property that goes missing, and injured borrowed things all come before the judges. A seduced maid is endowed to be her seducer's wife unless her father refuses; witchcraft, lying with beasts, and sacrificing to any god but the LORD are capital crimes. Israel must not vex a stranger — for they were strangers in Egypt — nor afflict the widow or fatherless, whose cry the Lord hears with hot wrath. The poor are not lent to upon usury, a pledged garment is returned by sundown, firstfruits and firstborn sons are given to God, and torn flesh is cast to the dogs as Israel becomes holy men unto Him.",
    context:"The covenant code continues with restitution for theft and property, and protection for the weak.",
    keyVerses:[
      { ref:"Exodus 22:1", text:"If a man shall steal an ox, or a sheep, and kill it, or sell it; he shall restore five oxen for an ox, and four sheep for a sheep." },
      { ref:"Exodus 22:21", text:"Thou shalt neither vex a stranger, nor oppress him: for ye were strangers in the land of Egypt." },
      { ref:"Exodus 22:26", text:"If thou at all take thy neighbour's raiment to pledge, thou shalt deliver it unto him by that the sun goeth down:" }
    ],
    takeaway:"True holiness shows in honest restitution and tender justice toward the stranger, the widow, the fatherless, and the poor.",
    quiz:[
      { q:"How many sheep had to be restored for one sheep stolen and killed or sold?", choices:["Two","Three","Five","Four"], a:3, why:"He shall restore five oxen for an ox, and four sheep for a sheep." },
      { q:"Why were Israelites forbidden to vex or oppress the stranger?", choices:["Because ye were strangers in the land of Egypt","Because strangers paid no taxes","Because they might leave the land","Because the stranger could not know the law"], a:0, why:"Thou shalt neither vex a stranger, nor oppress him: for ye were strangers in the land of Egypt." },
      { q:"What does returning a poor man's pledged garment by sundown show about the Lord?", choices:["The law cared more for property than people","He is gracious and hears when the poor cry to Him","Pledges were forbidden in every form","Loans to the poor were prohibited entirely"], a:1, why:"For that is his covering only... and it shall come to pass, when he crieth unto me, that I will hear; for I am gracious." }
    ] },
  { n:23, summary:"Justice must be clean: no false report, no joining the wicked as an unrighteous witness, no following a multitude to do evil, and no countenancing a poor man in his cause. Even an enemy's straying ox or ass is restored or helped up; judges refuse gifts, for the gift blindeth the wise, and the stranger is not oppressed, for Israel knows the stranger's heart. The land rests its seventh year for the poor and the beasts, and the seventh day refreshes servants and animals. Three feasts are kept yearly — unleavened bread in Abib, harvest of firstfruits, and ingathering at the year's end — and none shall appear before the LORD empty. An Angel goes before Israel with the Lord's name in him; obedience brings bread, water, health, and enemies turned to back, with hornets driving out the nations by little and little, lest the land be desolate. Israel must make no covenant with the nations or their gods.",
    context:"Justice, sabbaths, and the three yearly feasts are commanded, with promises of a gradual conquest of Canaan.",
    keyVerses:[
      { ref:"Exodus 23:2", text:"Thou shalt not follow a multitude to do evil; neither shalt thou speak in a cause to decline after many to wrest judgment:" },
      { ref:"Exodus 23:19", text:"The first of the firstfruits of thy land thou shalt bring into the house of the LORD thy God. Thou shalt not seethe a kid in his mother's milk." },
      { ref:"Exodus 23:30", text:"By little and little I will drive them out from before thee, until thou be increased, and inherit the land." }
    ],
    takeaway:"God's justice is unmoved by crowds or bribes, and His promises are kept little by little as His people obey.",
    quiz:[
      { q:"How many feasts was Israel commanded to keep unto the LORD each year?", choices:["One","Two","Three","Seven"], a:2, why:"Three times thou shalt keep a feast unto me in the year." },
      { q:"Why would the Lord not drive out the nations before Israel in one year?", choices:["Israel's army needed years of training","The nations were too strong to defeat","God wanted Israel to learn patience in war","Lest the land become desolate and the beasts of the field multiply"], a:3, why:"I will not drive them out from before thee in one year; lest the land become desolate, and the beast of the field multiply against thee." },
      { q:"What does 'thou shalt not follow a multitude to do evil' teach about moral courage?", choices:["Right is not decided by numbers; the crowd may be wrong","Popular causes are usually just","The poor should always be favored in judgment","Silence is the best response to injustice"], a:0, why:"Neither shalt thou speak in a cause to decline after many to wrest judgment — even majority opinion must not bend justice." }
    ] },
  { n:24, summary:"Moses tells the people all the LORD's words and judgments, and they answer with one voice, All the words which the LORD hath said will we do. He writes the words, rises early, and builds an altar under the hill with twelve pillars for the twelve tribes; young men offer burnt offerings and peace offerings. Half the blood is sprinkled on the altar; after reading the book of the covenant to the people, who promise again to do and be obedient, Moses sprinkles the blood on them: Behold the blood of the covenant. Moses, Aaron, Nadab, Abihu, and seventy elders go up and see the God of Israel, under whose feet is as it were a paved work of a sapphire stone, and they eat and drink. Then Moses is called up into the mount to receive tables of stone, a law, and commandments written by God; Joshua attends him while Aaron and Hur settle disputes below. The glory of the LORD abides on Sinai like devouring fire, and Moses is in the mount forty days and forty nights.",
    context:"Israel's elders confirm the covenant with sacrifice at Sinai before Moses ascends to receive the stone tables.",
    keyVerses:[
      { ref:"Exodus 24:7", text:"And he took the book of the covenant, and read in the audience of the people: and they said, All that the LORD hath said will we do, and be obedient." },
      { ref:"Exodus 24:8", text:"And Moses took the blood, and sprinkled it on the people, and said, Behold the blood of the covenant, which the LORD hath made with you concerning all these words." },
      { ref:"Exodus 24:18", text:"And Moses went into the midst of the cloud, and gat him up into the mount: and Moses was in the mount forty days and forty nights." }
    ],
    takeaway:"Covenants are answered with obedience, sealed with sacrifice, and confirmed by God's presence with His people.",
    quiz:[
      { q:"What did the twelve pillars around Moses' altar represent?", choices:["The twelve judges of Israel","The twelve tribes of Israel","The twelve months of the year","The twelve sons of Aaron"], a:1, why:"He builded an altar under the hill, and twelve pillars, according to the twelve tribes of Israel." },
      { q:"What did Moses, Aaron, Nadab, Abihu, and the seventy elders see and do on the mount?", choices:["They watched the tabernacle raised","They heard the ten commandments again","They saw the God of Israel, and did eat and drink","They received the priestly garments"], a:2, why:"They saw the God of Israel: and there was under his feet as it were a paved work of a sapphire stone... and did eat and drink." },
      { q:"How long was Moses in the mount receiving the tables of stone?", choices:["Seven days","Three days","Twelve days","Forty days and forty nights"], a:3, why:"Moses went into the midst of the cloud, and gat him up into the mount: and Moses was in the mount forty days and forty nights." }
    ] },
  { n:25, summary:"The Lord asks each Israelite to bring His offering willingly with his heart — gold, silver, brass, blue, purple, scarlet, fine linen, goats' hair, rams' skins dyed red, badgers' skins, shittim wood, oil for the light, spices, and onyx stones — that they may make Him a sanctuary, that He may dwell among them, built after the pattern shown in the mount. First comes the ark of shittim wood overlaid with pure gold within and without, carried by staves through golden rings, holding the testimony, and topped by a mercy seat of pure gold with two cherubims of beaten work whose wings cover it and whose faces look one to another; there, above the mercy seat, God will meet with Moses and commune with him. Then the table of shewbread with its golden vessels, set with bread before the Lord always, and the seven-lamped candlestick of a talent of pure gold, one beaten work with almond bowls, knops, and flowers.",
    context:"Sinai's tabernacle instructions open with the offering, the ark and mercy seat, the shewbread table, and the lampstand.",
    keyVerses:[
      { ref:"Exodus 25:2", text:"Speak unto the children of Israel, that they bring me an offering: of every man that giveth it willingly with his heart ye shall take my offering." },
      { ref:"Exodus 25:8", text:"And let them make me a sanctuary; that I may dwell among them." },
      { ref:"Exodus 25:22", text:"And there I will meet with thee, and I will commune with thee from above the mercy seat, from between the two cherubims which are upon the ark of the testimony, of all things which I will give thee in commandment unto the children of Israel." }
    ],
    takeaway:"God desires to dwell among a willing people; the sanctuary was built from hearts, not taxes.",
    quiz:[
      { q:"What wood, overlaid with pure gold, was used to build the ark?", choices:["Shittim wood","Cedar of Lebanon","Olive wood","Gopher wood"], a:0, why:"They shall make an ark of shittim wood... and thou shalt overlay it with pure gold, within and without." },
      { q:"From where did the Lord say He would meet and commune with Moses?", choices:["From the cloud above the altar of brass","From above the mercy seat, from between the two cherubims","From the shewbread table at dawn","From the door hanging of the tent"], a:1, why:"There I will meet with thee, and I will commune with thee from above the mercy seat, from between the two cherubims." },
      { q:"What does the command to build 'after the pattern' shown to Moses teach about worship?", choices:["Worship is shaped by God's revealed pattern, not human invention","Each generation may redesign the sanctuary freely","Patterns matter less than the amount given","Egyptian temples provided the true design"], a:2, why:"According to all that I shew thee, after the pattern of the tabernacle, and the pattern of all the instruments thereof, even so shall ye make it." }
    ] },
  { n:26, summary:"The tabernacle's fabric is specified: ten curtains of fine twined linen, blue, purple, and scarlet, with cherubims of cunning work, joined into one by fifty loops and fifty taches of gold; eleven curtains of goats' hair form the tent above, closed with taches of brass, and coverings of rams' skins dyed red and badgers' skins crown the whole. Boards of shittim wood, each ten cubits tall, stand on silver sockets — twenty on the south, twenty on the north, six with two corner boards on the west — bound together by five gold-overlaid bars per side. A veil of the same rich colors, wrought with cherubims and hung on four pillars, divides between the holy place and the most holy, where the mercy seat goes upon the ark; the table stands without on the north, the candlestick on the south, and a needlework hanging with five pillars forms the tent door.",
    context:"At Sinai the Lord details the tabernacle's curtains, coverings, boards, sockets, and the dividing veil.",
    keyVerses:[
      { ref:"Exodus 26:33", text:"And thou shalt hang up the veil under the taches, that thou mayest bring in thither within the veil the ark of the testimony: and the veil shall divide unto you between the holy place and the most holy." },
      { ref:"Exodus 26:1", text:"Moreover thou shalt make the tabernacle with ten curtains of fine twined linen, and blue, and purple, and scarlet: with cherubims of cunning work shalt thou make them." },
      { ref:"Exodus 26:30", text:"And thou shalt rear up the tabernacle according to the fashion thereof which was shewed thee in the mount." }
    ],
    takeaway:"Every layer of God's house taught approach: the way into His presence is appointed, guarded, and exact.",
    quiz:[
      { q:"How many curtains of fine twined linen made the tabernacle's inner covering?", choices:["Seven","Eleven","Twelve","Ten"], a:3, why:"Thou shalt make the tabernacle with ten curtains of fine twined linen, and blue, and purple, and scarlet." },
      { q:"What separated the holy place from the most holy?", choices:["A veil of blue, purple, scarlet, and fine twined linen with cherubims on four pillars","A wall of boards overlaid with brass","A curtain of goats' hair hung on six pillars","A linen screen tended by the Levites"], a:0, why:"The veil shall divide unto you between the holy place and the most holy." },
      { q:"Why did the tabernacle need a dividing veil before the ark and mercy seat?", choices:["To keep the furniture clean from dust","To teach that access to God's immediate presence is on His terms alone","To hide the beauty of the furnishings from visitors","Because the weather outside was severe"], a:1, why:"The ark and mercy seat rested in the most holy place, entered only as the Lord appointed — the veil marked that boundary." }
    ] },
  { n:27, summary:"The altar of burnt offering is a foursquare structure of shittim wood, five cubits long and broad and three cubits high, overlaid with brass, with horns on its four corners, a brasen grate, brass vessels — pans, shovels, basins, fleshhooks, and firepans — and staves for carrying; it is hollow with boards, made as was shewed in the mount. The court of the tabernacle is fenced with fine twined linen hangings, a hundred cubits on the south and north, fifty on the west, and an east side with a twenty-cubit gate hanging of blue, purple, scarlet, and needlework; its pillars stand in brasen sockets with silver hooks and fillets, and the whole court is five cubits high. Finally the children of Israel must bring pure oil olive beaten for the light, that the lamp may burn always: Aaron and his sons tend it in the tabernacle from evening to morning, a statute for ever unto their generations.",
    context:"The brasen altar, the court of the tabernacle, and the oil for the continually burning lamp are described.",
    keyVerses:[
      { ref:"Exodus 27:20", text:"And thou shalt command the children of Israel, that they bring thee pure oil olive beaten for the light, to cause the lamp to burn always." },
      { ref:"Exodus 27:1", text:"And thou shalt make an altar of shittim wood, five cubits long, and five cubits broad; the altar shall be foursquare: and the height thereof shall be three cubits." },
      { ref:"Exodus 27:21", text:"In the tabernacle of the congregation without the veil, which is before the testimony, Aaron and his sons shall order it from evening to morning before the LORD: it shall be a statute for ever unto their generations on the behalf of the children of Israel." }
    ],
    takeaway:"A lamp burned always before the Lord; devotion to Him is constant, tended by those He appoints.",
    quiz:[
      { q:"What metal covered the altar of burnt offering and all of its vessels?", choices:["Gold","Silver","Brass","Lambs' wool"], a:2, why:"His horns shall be of the same: and thou shalt overlay it with brass... all the vessels thereof thou shalt make of brass." },
      { q:"What oil did Israel bring so the lamp could burn always?", choices:["Any pressed oil from the harvest","Spiced oil like the anointing oil","Oil bought from Egypt","Pure oil olive beaten for the light"], a:3, why:"Thou shalt command the children of Israel, that they bring thee pure oil olive beaten for the light, to cause the lamp to burn always." },
      { q:"What does the command that the lamp burn 'always' teach about life before God?", choices:["Communion with God is continual, tended day and night, not occasional","Light was needed because worship happened only at noon","Only the high priest needed continual light","The lamps mattered more than the offerings"], a:0, why:"Aaron and his sons ordered the lamp from evening to morning before the LORD, a statute for ever." }
    ] },
  { n:28, summary:"Aaron and his sons — Nadab, Abihu, Eleazar, and Ithamar — are taken for the priest's office and clothed in holy garments for glory and for beauty, made by wise-hearted men whom God filled with the spirit of wisdom. The ephod of gold, blue, purple, scarlet, and fine twined linen carries two onyx stones on its shoulders, six tribal names engraved on each, so Aaron bears their names before the LORD for a memorial. The breastplate of judgment, a span square when doubled, holds four rows of twelve precious stones, each engraved with a tribe, and holds the Urim and the Thummim upon Aaron's heart. The robe of the ephod, all of blue, is hemmed with golden bells and pomegranates, that Aaron's sound may be heard when he enters and he die not. A plate of pure gold engraved HOLINESS TO THE LORD crowns the mitre, and linen coats, girdles, bonnets, and breeches complete the priests' garments.",
    context:"Aaron and his sons are appointed to the priest's office, and their holy garments are specified piece by piece.",
    keyVerses:[
      { ref:"Exodus 28:30", text:"And thou shalt put in the breastplate of judgment the Urim and the Thummim; and they shall be upon Aaron's heart, when he goeth in before the LORD: and Aaron shall bear the judgment of the children of Israel upon his heart before the LORD continually." },
      { ref:"Exodus 28:36", text:"And thou shalt make a plate of pure gold, and grave upon it, like the engravings of a signet, HOLINESS TO THE LORD." },
      { ref:"Exodus 28:12", text:"And thou shalt put the two stones upon the shoulders of the ephod for stones of memorial unto the children of Israel: and Aaron shall bear their names before the LORD upon his two shoulders for a memorial." }
    ],
    takeaway:"The priest carried the tribes on his shoulders and heart; those who serve God carry His people as a memorial.",
    quiz:[
      { q:"How many stones were set in the breastplate of judgment, and what did they bear?", choices:["Two, bearing the firstborn's name","Twelve, engraved with the names of the children of Israel","Seven, bearing the names of the feasts","Four, bearing the faces of the cherubims"], a:1, why:"The stones shall be with the names of the children of Israel, twelve, according to their names... according to the twelve tribes." },
      { q:"What words were engraved on the plate of pure gold on Aaron's mitre?", choices:["I AM THAT I AM","THE LORD IS MY STRENGTH","HOLINESS TO THE LORD","MINE ANOINTED"], a:2, why:"Thou shalt make a plate of pure gold, and grave upon it... HOLINESS TO THE LORD." },
      { q:"What did the Urim and the Thummim, placed in the breastplate, signify about the priest's role?", choices:["They recorded the years of service","They decorated the garment for festivals","They marked the priest's tribe among the twelve","They were borne upon Aaron's heart for the judgment of Israel before the LORD"], a:3, why:"Thou shalt put in the breastplate of judgment the Urim and the Thummim; and Aaron shall bear the judgment of the children of Israel upon his heart before the LORD continually." }
    ] },
  { n:29, summary:"Aaron and his sons are hallowed for the priest's office in a seven-day ceremony: washed with water, clothed in the holy garments, and anointed with oil. A bullock is offered for a sin offering, a ram wholly burned for a burnt offering, and a second ram of consecration whose blood is put on the tip of the right ear, the thumb of the right hand, and the great toe of the right foot of Aaron and his sons. Wave offerings of fat, the right shoulder, and bread from the basket are burned or become Aaron's portion by statute for ever, and the priests eat the ram and the bread at the tabernacle door. The altar itself is atoned for and anointed seven days to be most holy. The chapter closes with the continual offering: two lambs of the first year day by day, one in the morning and the other at even, where the Lord will meet Israel — I will dwell among the children of Israel, and will be their God.",
    context:"Sinai's instructions continue with the seven-day ceremony consecrating Aaron and his sons and the daily sacrifices.",
    keyVerses:[
      { ref:"Exodus 29:45", text:"And I will dwell among the children of Israel, and will be their God." },
      { ref:"Exodus 29:38", text:"Now this is that which thou shalt offer upon the altar; two lambs of the first year day by day continually." },
      { ref:"Exodus 29:20", text:"Then shalt thou kill the ram, and take of his blood, and put it upon the tip of the right ear of Aaron, and upon the tip of the right ear of his sons, and upon the thumb of their right hand, and upon the great toe of their right foot, and sprinkle the blood upon the altar round about." }
    ],
    takeaway:"Consecration sets servants apart wholly — ear to hear, hand to work, foot to walk — and daily sacrifice keeps worship continual.",
    quiz:[
      { q:"Which animals were required for the consecration ceremony?", choices:["One young bullock and two rams without blemish","Two bullocks and one kid","Seven lambs and one he goat","One bullock, one ram, and a turtledove"], a:0, why:"Take one young bullock, and two rams without blemish... and thou shalt kill the bullock before the LORD." },
      { q:"How many days were Aaron and his sons to be consecrated?", choices:["Three days","Seven days","Forty days","Twelve days"], a:1, why:"Seven days shalt thou consecrate them." },
      { q:"What does the daily offering of two lambs, one in the morning and one at even, teach about devotion?", choices:["Evening worship is more acceptable than morning worship","Offerings were needed only on feast days","Commitment to God is renewed continually, morning and evening","Sacrifices ended once the altar was anointed"], a:2, why:"Two lambs of the first year day by day continually... a continual burnt offering throughout your generations at the door of the tabernacle." }
    ] },
  { n:30, summary:"An altar to burn incense — shittim wood overlaid with pure gold, a cubit square and two cubits high with horns — stands before the veil by the ark. Aaron burns sweet incense on it every morning when he dresses the lamps and at even when he lights them, a perpetual incense; no strange incense, burnt sacrifice, meat offering, or drink offering may touch it, and its horns are atoned for once a year. When Israel is numbered, every man from twenty years old gives half a shekel, a ransom for his soul — the rich not more, the poor not less — appointed for the tabernacle's service. A laver of brass between the tabernacle and altar supplies water for Aaron and his sons to wash their hands and feet, that they die not. Recipes follow for the holy anointing oil and the pure incense; both are most holy, and whoever imitates them for common use is cut off from his people.",
    context:"The incense altar, census half shekel, brass laver, anointing oil, and holy incense complete the appointments.",
    keyVerses:[
      { ref:"Exodus 30:15", text:"The rich shall not give more, and the poor shall not give less than half a shekel, when they give an offering unto the LORD, to make an atonement for your souls." },
      { ref:"Exodus 30:1", text:"And thou shalt make an altar to burn incense upon: of shittim wood shalt thou make it." },
      { ref:"Exodus 30:19", text:"For Aaron and his sons shall wash their hands and their feet thereat:" }
    ],
    takeaway:"Nearness to God is guarded by purity and reverence: holy things are treated as holy, and worship is never casual.",
    quiz:[
      { q:"How much did every numbered Israelite twenty years old and above give as an offering?", choices:["A full shekel","Two shekels","Ten gerahs","Half a shekel"], a:3, why:"An half shekel shall be the offering of the LORD... the rich shall not give more, and the poor shall not give less." },
      { q:"When did Aaron burn the sweet incense on the golden altar?", choices:["Every morning when he dressed the lamps and every evening when he lighted them","Only on the day of atonement","Once each sabbath","Whenever the congregation gathered"], a:0, why:"Aaron shall burn thereon sweet incense every morning: when he dresseth the lamps... and when he lighteth the lamps at even." },
      { q:"Why did the priests wash their hands and feet at the laver before ministering?", choices:["To prepare for the census tax","So they would not die, serving before a holy God","To symbolize the washing of Israel's garments","Because the desert water was scarce"], a:1, why:"They shall wash with water, that they die not... so they shall wash their hands and their feet, that they die not." }
    ] },
  { n:31, summary:"The Lord calls Bezaleel, son of Uri and grandson of Hur, of the tribe of Judah, by name, filling him with the spirit of God in wisdom, understanding, knowledge, and all manner of workmanship — to devise cunning works in gold, silver, brass, stone, and timber. Aholiab, son of Ahisamach of the tribe of Dan, is given with him, and wisdom is put into every wise-hearted heart to make the tabernacle, the ark and mercy seat, the furniture, garments, anointing oil, and incense. The sabbaths are then appointed a sign between the LORD and Israel throughout their generations, a perpetual covenant: six days may work be done, but everyone who defiles the seventh day is put to death or cut off, for in six days the LORD made heaven and earth, and on the seventh He rested and was refreshed. The chapter ends with the Lord giving Moses two tables of testimony, tables of stone, written with the finger of God.",
    context:"Two Spirit-filled craftsmen are named for the tabernacle, the sabbath is made a sign, and the stone tables are given.",
    keyVerses:[
      { ref:"Exodus 31:18", text:"And he gave unto Moses, when he had made an end of communing with him upon mount Sinai, two tables of testimony, tables of stone, written with the finger of God." },
      { ref:"Exodus 31:3", text:"And I have filled him with the spirit of God, in wisdom, and in understanding, and in knowledge, and in all manner of workmanship," },
      { ref:"Exodus 31:16", text:"Wherefore the children of Israel shall keep the sabbath, to observe the sabbath throughout their generations, for a perpetual covenant." }
    ],
    takeaway:"God names and fills particular people with His Spirit for His work, and seals His covenant people with holy rest.",
    quiz:[
      { q:"Of which tribe was Bezaleel, the master craftsman of the sanctuary?", choices:["Levi","Dan","Judah","Benjamin"], a:2, why:"I have called by name Bezaleel the son of Uri, the son of Hur, of the tribe of Judah." },
      { q:"Who wrote on the two tables of stone given to Moses at the chapter's close?", choices:["Moses, writing as he was dictated","Aaron, the appointed scribe","The seventy elders of Israel","God — the writing was with the finger of God"], a:3, why:"He gave unto Moses... two tables of testimony, tables of stone, written with the finger of God." },
      { q:"What does the Lord filling Bezaleel with the spirit of God teach about skills and talents?", choices:["Craftsmanship can be a Spirit-given gift devoted to God's service","Only priests and prophets receive God's Spirit","Manual skills are lower callings than preaching","Talent comes solely from long practice"], a:0, why:"I have filled him with the spirit of God, in wisdom... to devise cunning works, to work in gold, and in silver, and in brass." }
    ] },
  { n:32, summary:"With Moses delayed in the mount, the people gather to Aaron, demanding gods to go before them. Aaron collects their golden earrings, fashions a molten calf, builds an altar, and proclaims a feast to the LORD — and the people offer, sit down to eat and drink, and rise up to play. The Lord sends Moses down, calls the people stiffnecked, and offers to consume them and make of Moses a great nation; Moses pleads the Egyptians' watching eyes and the oath sworn to Abraham, Isaac, and Israel, and the LORD repents of the evil He thought to do. Descending with the tables God Himself had written, Moses sees the calf and the dancing and shatters the tables, burns and grinds the calf to powder strown on the water, and confronts Aaron's feeble excuse. The sons of Levi rally to his cry, Who is on the LORD's side?, and about three thousand men fall. Moses asks to be blotted from God's book for his people; the LORD sends them onward by His Angel, yet plagued the people for the calf.",
    context:"While Moses receives the law above on Sinai, Israel below melts its gold into a calf and worships it.",
    keyVerses:[
      { ref:"Exodus 32:4", text:"And he received them at their hand, and fashioned it with a graving tool, after he had made it a molten calf: and they said, These be thy gods, O Israel, which brought thee up out of the land of Egypt." },
      { ref:"Exodus 32:14", text:"And the LORD repented of the evil which he thought to do unto his people." },
      { ref:"Exodus 32:26", text:"Then Moses stood in the gate of the camp, and said, Who is on the LORD's side? let him come unto me. And all the sons of Levi gathered themselves together unto him." }
    ],
    takeaway:"Idolatry corrupts quickly after great revelation; bold intercession and clear loyalty to the LORD stand between judgment and mercy.",
    quiz:[
      { q:"What image did Aaron fashion from the people's golden earrings?", choices:["A golden serpent","A molten calf","A golden ark","A cherub of gold"], a:1, why:"He fashioned it with a graving tool, after he had made it a molten calf: and they said, These be thy gods, O Israel." },
      { q:"On what grounds did Moses plead for Israel when God offered to consume them?", choices:["Israel's promise of future obedience","The priesthood of Aaron and his sons","God's oath to Abraham, Isaac, and Israel and His reputation before the Egyptians","The gold and jewels Israel carried out of Egypt"], a:2, why:"Moses begged the Lord to remember Abraham, Isaac, and Israel, to whom He sware He would multiply their seed, and warned what the Egyptians would say." },
      { q:"What does Aaron's excuse — he cast the gold into the fire, 'and there came out this calf' — warn leaders against?", choices:["Working with gold without supervision","Building altars without a feast","Leaving the people without food","Dodging responsibility for what happens on their watch"], a:3, why:"Aaron blamed the people's mischief and the fire, but the calf was made which Aaron made — he had shaped it himself." }
    ] },
  { n:33, summary:"The Lord commands Israel to depart for the land sworn to Abraham, Isaac, and Jacob, but He will not go up in the midst of this stiffnecked people, lest He consume them; an angel will drive out the Canaanites instead. Moses pitches the tabernacle of the congregation afar off without the camp, and everyone who sought the LORD went out to it; the cloudy pillar descends at its door, and the LORD speaks with Moses face to face, as a man speaketh unto his friend. Moses pleads: if I have found grace in thy sight, shew me thy way. The Lord answers, My presence shall go with thee, and I will give thee rest — and Moses refuses to move unless His presence goes with them. Then he asks boldly, Shew me thy glory; the Lord will make all His goodness pass before him, but no man can see His face and live, so Moses stands in a clift of the rock, covered, to see His back parts.",
    context:"After the calf, the Lord's immediate presence is withdrawn to the tabernacle outside the camp, and Moses intercedes.",
    keyVerses:[
      { ref:"Exodus 33:11", text:"And the LORD spake unto Moses face to face, as a man speaketh unto his friend. And he turned again into the camp: but his servant Joshua, the son of Nun, a young man, departed not out of the tabernacle." },
      { ref:"Exodus 33:14", text:"And he said, My presence shall go with thee, and I will give thee rest." },
      { ref:"Exodus 33:20", text:"And he said, Thou canst not see my face: for there shall no man see me, and live." }
    ],
    takeaway:"What sets God's people apart is not the promised land but the promised presence going with them.",
    quiz:[
      { q:"Where did Moses pitch the tabernacle of the congregation in this chapter?", choices:["Afar off, outside the camp","In the court beside the altar","On the top of mount Sinai","In the midst of the congregation"], a:0, why:"Moses took the tabernacle, and pitched it without the camp, afar off from the camp." },
      { q:"What did Moses refuse to go forward without, though an angel was promised?", choices:["The tables of the law","The Lord's own presence going with them","The golden ornaments of the people","Aaron and the seventy elders"], a:1, why:"If thy presence go not with me, carry us not up hence — for God's presence marked Israel off from all people on the earth." },
      { q:"What does Moses being hidden in the clift of the rock while glory passes teach about seeing God?", choices:["God's glory is visible to all who ask boldly","God reveals Himself according to His terms, for no man can see His face and live","Mountains are the proper places to meet God","Those who seek signs are turned away"], a:2, why:"Thou canst not see my face: for there shall no man see me, and live — yet the Lord covered Moses and let him see His back parts." }
    ] },
  { n:34, summary:"Moses hews two tables of stone like the first and climbs Sinai alone at dawn. The Lord descends in the cloud, stands with him, and proclaims His name: The LORD, The LORD God, merciful and gracious, longsuffering, and abundant in goodness and truth, keeping mercy for thousands, forgiving iniquity and transgression and sin, and that will by no means clear the guilty. Moses bows and worships and pleads for the Lord to go among Israel and pardon their sin. God covenants to do marvels never seen, commands destroying Canaanite altars and images, forbids covenants with the land's inhabitants, and warns: Thou shalt worship no other god: for the LORD, whose name is Jealous, is a jealous God. Commands follow for no molten gods, the sabbath, the feasts, firstlings, and three yearly appearances. Forty days without bread or water, Moses writes the words of the covenant, the ten commandments; descending, his face shines so that Aaron and Israel fear to come nigh, and he veils his face among the people.",
    context:"Moses ascends Sinai with new tables; the Lord proclaims His name, renews the covenant, and Moses' face shines.",
    keyVerses:[
      { ref:"Exodus 34:6", text:"And the LORD passed by before him, and proclaimed, The LORD, The LORD God, merciful and gracious, longsuffering, and abundant in goodness and truth," },
      { ref:"Exodus 34:14", text:"For thou shalt worship no other god: for the LORD, whose name is Jealous, is a jealous God:" },
      { ref:"Exodus 34:29", text:"And it came to pass, when Moses came down from mount Sinai with the two tables of testimony in Moses' hand, when he came down from the mount, that Moses wist not that the skin of his face shone while he talked with him." }
    ],
    takeaway:"God renews covenant with the fallen, revealing Himself as merciful, gracious, and longsuffering — yet never excusing guilt.",
    quiz:[
      { q:"What did Moses do without during the forty days and nights of this second stay on the mount?", choices:["Speaking to the Lord","Resting or sleeping","Descending to the camp","Eating bread and drinking water"], a:3, why:"He was there with the LORD forty days and forty nights; he did neither eat bread, nor drink water." },
      { q:"What name does the Lord attach to Himself when forbidding worship of other gods?", choices:["Jealous","Patient","Hidden","Terrible"], a:0, why:"Thou shalt worship no other god: for the LORD, whose name is Jealous, is a jealous God." },
      { q:"What does the Lord's proclamation — merciful, gracious, forgiving, yet by no means clearing the guilty — teach about His character?", choices:["God forgives sin so completely that guilt disappears for everyone","Mercy and justice are both essential to who God is","God's patience means judgment will never come","Only Israelites may appeal to His mercy"], a:1, why:"The Lord keeps mercy for thousands, forgiving iniquity and transgression and sin, and that will by no means clear the guilty." }
    ] },
  { n:35, summary:"Moses gathers all the congregation and repeats the sabbath command: work six days, keep the seventh an holy day of rest to the LORD, on pain of death, and kindle no fire in habitations on the sabbath. He then relays the Lord's call for an offering from every willing heart — gold, silver, brass, colored threads, fine linen, goats' hair, dyed rams' skins, badgers' skins, shittim wood, oil, spices, and onyx stones — for all the work of the tabernacle and the holy garments. The congregation departs and comes back pouring out gifts: men and women bring jewels of gold, silver, and brass, wise-hearted women spin blue, purple, scarlet, and goats' hair, and the rulers bring onyx stones, spice, and oil — everyone whose heart stirred him up. Moses announces that the LORD has called Bezaleel of Judah, filled him with the spirit of God in wisdom and workmanship, and with Aholiab of Dan has put into their hearts wisdom to work and to teach.",
    context:"After Sinai, Moses relays the sabbath command, calls for willing offerings, and presents Bezaleel and Aholiab to the people.",
    keyVerses:[
      { ref:"Exodus 35:21", text:"And they came, every one whose heart stirred him up, and every one whom his spirit made willing, and they brought the LORD's offering to the work of the tabernacle of the congregation, and for all his service, and for the holy garments." },
      { ref:"Exodus 35:5", text:"Take ye from among you an offering unto the LORD: whosoever is of a willing heart, let him bring it, an offering of the LORD; gold, and silver, and brass," },
      { ref:"Exodus 35:34", text:"And he hath put in his heart that he may teach, both he, and Aholiab, the son of Ahisamach, of the tribe of Dan." }
    ],
    takeaway:"God asks for willing hearts, and stirred hearts give; Spirit-filled workers also teach others the craft.",
    quiz:[
      { q:"What sabbath restriction was added when Moses repeated the command to the congregation?", choices:["No one might leave the camp","No bread could be baked","Ye shall kindle no fire throughout your habitations upon the sabbath day","Tools had to be buried before sundown"], a:2, why:"Ye shall kindle no fire throughout your habitations upon the sabbath day." },
      { q:"Who brought the onyx stones and spices for the ephod, breastplate, and incense?", choices:["The priests alone","The Levite musicians","The midwives of Israel","The rulers"], a:3, why:"The rulers brought onyx stones, and stones to be set, for the ephod, and for the breastplate; and spice, and oil." },
      { q:"What does the response to the call for offerings reveal about giving prompted by the heart?", choices:["People whom God stirs give freely beyond the need","Giving should be enforced by strict quotas","Only the wealthy contribute to sacred work","Gifts matter only when large"], a:0, why:"They came, every one whose heart stirred him up, and every one whom his spirit made willing, and brought the LORD's offering." }
    ] },
  { n:36, summary:"Bezaleel, Aholiab, and every wise-hearted man in whom the LORD put wisdom begin the sanctuary's work, receiving from Moses the children of Israel's offering — which keeps arriving every morning. At last the craftsmen leave their tasks to report: The people bring much more than enough. Moses commands a proclamation through the camp that no man or woman make any more for the offering, and the people are restrained from bringing, for the stuff they had was sufficient for all the work to make it, and too much. The rest of the chapter mirrors the Sinai specification as built: ten cherubim-covered linen curtains joined with golden taches, eleven goats' hair curtains, coverings of rams' skins and badgers' skins, boards of shittim wood on silver sockets with gold-overlaid bars, the veil of cunning work on four pillars, and the needlework hanging for the door on its five pillars.",
    context:"The tabernacle's construction begins, and the people's offerings are so abundant that Moses commands them to stop.",
    keyVerses:[
      { ref:"Exodus 36:5", text:"And they spake unto Moses, saying, The people bring much more than enough for the service of the work, which the LORD commanded to make." },
      { ref:"Exodus 36:7", text:"For the stuff they had was sufficient for all the work to make it, and too much." },
      { ref:"Exodus 36:1", text:"Then wrought Bezaleel and Aholiab, and every wise hearted man, in whom the LORD put wisdom and understanding to know how to work all manner of work for the service of the sanctuary, according to all that the LORD had commanded." }
    ],
    takeaway:"Willing givers can outgive the work; restraint that ends the offering honors generosity by meeting need, not exhausting it.",
    quiz:[
      { q:"Which two craftsmen led the making of the tabernacle's curtains and boards?", choices:["Hur and Uri","Bezaleel and Aholiab","Aaron and Eleazar","Joshua and Caleb"], a:1, why:"Then wrought Bezaleel and Aholiab, and every wise hearted man, in whom the LORD put wisdom and understanding." },
      { q:"What extraordinary step did Moses have to take during the construction?", choices:["He appointed guards to watch the materials","He doubled the daily work quotas","He proclaimed that no one should bring more offerings","He asked Pharaoh's engineers for help"], a:2, why:"The people bring much more than enough, so Moses proclaimed throughout the camp that neither man nor woman make any more work for the offering." },
      { q:"What does the overflowing response to the offering call teach about a stirred community?", choices:["Communities give most when compelled by law","Excess generosity usually signals poor planning","Wise-hearted workers should refuse excess supplies","Willing hearts give beyond the need, and restraint becomes necessary"], a:3, why:"The stuff they had was sufficient for all the work to make it, and too much — so the people were restrained from bringing." }
    ] },
  { n:37, summary:"Bezaleel makes the sanctuary's furniture of gold. The ark of shittim wood, overlaid with pure gold within and without, receives its golden crown, four rings, and staves; upon it rests the mercy seat of pure gold, with two cherubims of beaten gold at its two ends, wings spread on high and faces toward the mercy seat. Next comes the table of shittim wood overlaid with gold, its crown, border, rings, staves, and vessels of dishes, spoons, bowls, and covers of pure gold. Then the candlestick of beaten work, its shaft, branches, almond bowls, knops, and flowers all one piece of a talent of pure gold, with seven lamps, snuffers, and snuffdishes. Last, the incense altar — shittim wood overlaid with gold, foursquare with horns — and the holy anointing oil and pure incense of sweet spices, made after the apothecary's art.",
    context:"Bezaleel makes the ark, mercy seat, shewbread table, seven-lamp candlestick, and incense altar to specification.",
    keyVerses:[
      { ref:"Exodus 37:1", text:"And Bezaleel made the ark of shittim wood: two cubits and a half was the length of it, and a cubit and a half the breadth of it, and a cubit and a half the height of it:" },
      { ref:"Exodus 37:9", text:"And the cherubims spread out their wings on high, and covered with their wings over the mercy seat, with their faces one to another; even to the mercy seatward were the faces of the cherubims." },
      { ref:"Exodus 37:24", text:"Of a talent of pure gold made he it, and all the vessels thereof." }
    ],
    takeaway:"Skilled obedience turns God's pattern into a place for His presence; holy work is done exactly as spoken.",
    quiz:[
      { q:"What covered the ark of the testimony inside and out?", choices:["Pure gold","Brass","Fine twined linen","Beaten silver"], a:0, why:"He overlaid it with pure gold within and without, and made a crown of gold to it round about." },
      { q:"How were the two cherubims of the mercy seat made?", choices:["Carved of olive wood and gilded","Beaten out of gold, of one piece with the mercy seat at its ends","Cast in brass and set beside the ark","Woven into the veil in gold thread"], a:1, why:"He made two cherubims of gold, beaten out of one piece made he them, on the two ends of the mercy seat." },
      { q:"How much gold was used for the candlestick and all its vessels?", choices:["Half a talent","Seven hundred shekels","A talent of pure gold","An hundred shekels"], a:2, why:"Of a talent of pure gold made he it, and all the vessels thereof." }
    ] },
  { n:38, summary:"The brasen altar of burnt offering is built — five cubits square, three high, overlaid with brass, with horns, grate, vessels, and staves — and the laver of brass with its foot is made from the lookingglasses of the women who assembled at the door of the tabernacle. The court is completed with fine linen hangings, their pillars and brasen sockets, silver hooks and fillets, and the needlework gate hanging. Then the tabernacle's accounting is rendered by Ithamar, son to Aaron the priest, while Bezaleel of Judah made all that the LORD commanded Moses, with Aholiab of Dan the engraver and embroiderer beside him. The gold of the offering came to twenty and nine talents, and seven hundred and thirty shekels; the silver to an hundred talents and a thousand seven hundred and threescore and fifteen shekels — a bekah, half a shekel, for each of the six hundred thousand and three thousand and five hundred and fifty men numbered; and the brass to seventy talents, and two thousand and four hundred shekels.",
    context:"The brasen altar, laver, and court are built, and the tabernacle's gold, silver, and brass are counted openly.",
    keyVerses:[
      { ref:"Exodus 38:8", text:"And he made the laver of brass, and the foot of it of brass, of the lookingglasses of the women assembling, which assembled at the door of the tabernacle of the congregation." },
      { ref:"Exodus 38:21", text:"This is the sum of the tabernacle, even of the tabernacle of testimony, as it was counted, according to the commandment of Moses, for the service of the Levites, by the hand of Ithamar, son to Aaron the priest." },
      { ref:"Exodus 38:26", text:"A bekah for every man, that is, half a shekel, after the shekel of the sanctuary, for every one that went to be numbered, from twenty years old and upward, for six hundred thousand and three thousand and five hundred and fifty men." }
    ],
    takeaway:"Freely given gifts for God's house are counted openly; sacred work is done in the light with honest accounting.",
    quiz:[
      { q:"From what were the brass laver and its foot made?", choices:["Brass left from the altar grate","Captured Egyptian armor","The pins of the court","The lookingglasses of the women assembling at the tabernacle door"], a:3, why:"He made the laver of brass, and the foot of it of brass, of the lookingglasses of the women assembling, which assembled at the door of the tabernacle." },
      { q:"Who counted the sum of the tabernacle for the service of the Levites?", choices:["Ithamar, son to Aaron the priest","Eleazar, the elder son of Aaron","Joshua, the captain","Kohath, chief of the Levites"], a:0, why:"This is the sum of the tabernacle... as it was counted, according to the commandment of Moses, for the service of the Levites, by the hand of Ithamar." },
      { q:"How many men were numbered, each giving the half-shekel bekah that supplied the silver?", choices:["Four hundred thousand and five hundred","Six hundred thousand and three thousand and five hundred and fifty","Seven hundred thousand and seven hundred","Six hundred and thirteen"], a:1, why:"A bekah for every man... for six hundred thousand and three thousand and five hundred and fifty men." }
    ] },
  { n:39, summary:"The holy garments are made as the LORD commanded Moses: the ephod of gold, blue, purple, scarlet, and fine twined linen, with onyx stones in golden ouches engraved with the names of Israel on its shoulders; the foursquare, doubled breastplate bearing four rows of twelve stones for the twelve tribes, fastened to the ephod with a lace of blue; the all-blue robe of the ephod, hemmed with pomegranates and golden bells; fine linen coats for Aaron and his sons, the mitre, goodly bonnets, linen breeches, and the needlework girdle; and the plate of the holy crown of pure gold, engraved like a signet, HOLINESS TO THE LORD. Thus was all the work of the tabernacle of the tent of the congregation finished, and the children of Israel brought every piece — tent, furniture, ark, mercy seat, table, candlestick, altars, hangings, and garments — to Moses. He looked upon all the work, saw they had done it as the LORD commanded, and blessed them.",
    context:"The holy garments are finished and every completed piece of the tabernacle is brought to Moses for inspection.",
    keyVerses:[
      { ref:"Exodus 39:32", text:"Thus was all the work of the tabernacle of the tent of the congregation finished: and the children of Israel did according to all that the LORD commanded Moses, so did they." },
      { ref:"Exodus 39:30", text:"And they made the plate of the holy crown of pure gold, and wrote upon it a writing, like to the engravings of a signet, HOLINESS TO THE LORD." },
      { ref:"Exodus 39:43", text:"And Moses did look upon all the work, and, behold, they had done it as the LORD had commanded, even so had they done it: and Moses blessed them." }
    ],
    takeaway:"Finished obedience is a blessing: when the work is done as the LORD commanded, the worker is blessed.",
    quiz:[
      { q:"What refrain runs through this chapter as each garment is described?", choices:["According to the wisdom of Egypt","After the fashion of the princes","As the LORD commanded Moses","By the hands of the women spinners"], a:2, why:"Verse after verse closes with as the LORD commanded Moses — the work matched the instruction exactly." },
      { q:"How did the chapter end after the finished work was brought to Moses?", choices:["The priests wore the garments at once","The people feasted seven days","The work was stored until the new year","Moses looked upon all the work and blessed them"], a:3, why:"Moses did look upon all the work, and, behold, they had done it as the LORD had commanded: and Moses blessed them." },
      { q:"What does building each piece exactly to specification teach about service to God?", choices:["Obedience in details honors the God who gave them","Creativity should replace the given pattern over time","Beauty matters more than faithfulness to instruction","Finished work excuses shortcuts taken along the way"], a:0, why:"They had done it as the LORD had commanded, even so had they done it: and Moses blessed them." }
    ] },
  { n:40, summary:"On the first day of the first month in the second year, the tabernacle is reared up. The Lord dictates the arrangement: the ark within, covered by the veil; the table with its bread set in order; the candlestick with its lamps lighted; the golden incense altar before the ark; the altar of burnt offering before the door; the laver with water between tent and altar; and the court with its gate hanging. Moses anoints the tabernacle and all its vessels with the holy oil, then washes, clothes, and anoints Aaron and his sons for an everlasting priesthood. Thus did Moses: according to all that the LORD commanded him, so did he — and Moses finished the work. Then a cloud covers the tent of the congregation, and the glory of the LORD fills the tabernacle, so that Moses cannot enter. By that cloud Israel journeys or waits, the cloud of the LORD by day and fire by night in the sight of all the house of Israel, throughout all their journeys.",
    context:"On the first day of the first month of the second year, Moses erects the tabernacle, and the glory of the LORD fills it.",
    keyVerses:[
      { ref:"Exodus 40:34", text:"Then a cloud covered the tent of the congregation, and the glory of the LORD filled the tabernacle." },
      { ref:"Exodus 40:17", text:"And it came to pass in the first month in the second year, on the first day of the month, that the tabernacle was reared up." },
      { ref:"Exodus 40:38", text:"For the cloud of the LORD was upon the tabernacle by day, and fire was on it by night, in the sight of all the house of Israel, throughout all their journeys." }
    ],
    takeaway:"When the work is finished as the Lord commanded, His glory comes to dwell and His presence directs every step.",
    quiz:[
      { q:"When was the tabernacle reared up?", choices:["On the last day of the first year of wandering","On the first day of the first month in the second year","On the anniversary of the passover night","Three months after leaving Egypt"], a:1, why:"It came to pass in the first month in the second year, on the first day of the month, that the tabernacle was reared up." },
      { q:"What happened as soon as Moses finished the work?", choices:["The people broke camp at once","Aaron offered the two daily lambs","A cloud covered the tent, and the glory of the LORD filled the tabernacle","The tables of the law were read aloud"], a:2, why:"Then a cloud covered the tent of the congregation, and the glory of the LORD filled the tabernacle; Moses was not able to enter." },
      { q:"What does the cloud and fire over the tabernacle teach about following God?", choices:["Guidance is needed only at major decisions","Israel followed the seasons in planting and harvest","The leaders alone determined when to move","God's people move or stay according to His visible presence"], a:3, why:"When the cloud was taken up they journeyed; if it were not taken up, they journeyed not — by day cloud, by night fire." }
    ] }
);
